"""Original tuberculosis chapter: diagnostic and treatment principles."""
from qbank_authoring import question,ref,finalize
DX=ref('WHO: Consolidated TB Guidelines, Module 3—Diagnosis, 2025','https://www.who.int/publications/i/item/9789240107984')
TX=ref('WHO: Consolidated TB Guidelines, Module 4—Treatment and Care, 2025','https://www.who.int/publications/i/item/9789240107243')
CD=ref('CDC: Treatment for Drug-Susceptible TB Disease','https://www.cdc.gov/tb/hcp/treatment/tuberculosis-disease.html')
LT=ref('CDC: Clinical and Laboratory Diagnosis for TB','https://www.cdc.gov/tb/hcp/testing-diagnosis/clinical-and-laboratory-diagnosis.html')
DR=ref('WHO: Updated Definitions of Pre-XDR and XDR Tuberculosis','https://www.who.int/news/item/27-01-2021-who-announces-updated-definitions-of-extensively-drug-resistant-tuberculosis')
AE=ref('CDC: Adverse Events During TB Treatment','https://www.cdc.gov/tb/hcp/treatment/adverse-events.html')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An adult has chronic cough, weight loss and an upper-lobe cavity. Under WHO 2025 diagnostic guidance, which initial respiratory test is preferred where available?', 'A WHO-recommended rapid molecular test detecting TB and relevant resistance markers',[
 ('Sputum smear microscopy as the only test','Smear lacks species specificity and rapid resistance information and is less sensitive.'),('IGRA as confirmation of active pulmonary disease','Immune sensitization does not distinguish active from latent infection.'),('A therapeutic trial of fluoroquinolone alone','This can delay diagnosis and select resistance.')],
 'Rapid molecular diagnosis can connect detection with resistance assessment', '**Use an appropriate molecular assay on a respiratory specimen.**',['A negative result does not exclude every paucibacillary case.','Culture and further susceptibility testing remain important when indicated.'], '**Treat the clinical probability and infection-control risk seriously.**',['Obtain adequate samples and investigate alternatives.','Do not delay necessary care in a severely ill patient while awaiting complete results.'],[['Molecular assay','Rapid organism and selected resistance detection'],['Smear','Limited sensitivity and no full susceptibility profile'],['Culture','Additional confirmation and susceptibility work']],[DX],style='clinical_scenario')
q('Which statement about an acid-fast-positive sputum smear is correct?', 'It demonstrates acid-fast organisms but does not by itself distinguish M. tuberculosis from nontuberculous mycobacteria',[
 ('It confirms rifampicin susceptibility','Smear provides no drug susceptibility result.'),('It excludes nontuberculous mycobacteria','Several mycobacteria are acid-fast.'),('It proves that a positive IGRA is due to current disease','The tests address different biological questions.')],
 'Microscopy is not species identification', '**Acid-fast staining identifies a staining property.**',['Molecular identification and culture provide complementary information.','Smear positivity also informs the potential transmission assessment.'], '**Interpret the result in the clinical and epidemiological setting.**',['Use rapid TB identification and resistance testing where available.','A negative smear does not exclude pulmonary TB.'],[['Smear positive','Acid-fast organisms present'],['Species','Requires further testing'],['Resistance','Requires molecular or phenotypic assessment']],[DX,LT])
q('A symptomatic immunosuppressed patient has a negative IGRA but imaging strongly suggests TB. What is the best interpretation?', 'Active TB remains possible and needs organism-directed evaluation',[
 ('A negative IGRA reliably excludes active TB','Immune tests have inadequate sensitivity for that purpose.'),('The result proves bacterial CAP instead','It does not identify another cause.'),('Sputum testing is unnecessary unless IGRA becomes positive','That would delay appropriate investigation.')],
 'Tests of immune sensitization are not rule-out tests for active disease', '**A negative IGRA does not settle a high-probability active-TB presentation.**',['Immunosuppression may reduce responses.','Disease can be paucibacillary or disseminated.'], '**Obtain specimens from the relevant disease site.**',['Respiratory and selected nonrespiratory testing may be complementary.','Maintain appropriate infection-control measures while investigating.'],[['IGRA','Immune sensitization'],['Active TB evaluation','Clinical, imaging and microbiology'],['Negative result','Does not exclude disease']],[DX,LT],style='clinical_scenario')
q('An adult has a positive IGRA before TNF-inhibitor treatment. What must occur before prescribing a latent-TB regimen?', 'Evaluate and reasonably exclude active TB disease',[
 ('Start isoniazid monotherapy immediately despite active symptoms','Monotherapy is inadequate for active disease and can select resistance.'),('Assume prior BCG fully explains the IGRA','IGRA antigens are not those of BCG vaccination.'),('Repeat IGRA monthly until it becomes negative','Serial conversion to negativity is not the required pre-treatment assessment.')],
 'Separate infection from disease before preventive treatment', '**A positive immune test alone does not identify the disease state.**',['Review symptoms and imaging.','Obtain microbiology when findings suggest active disease.'], '**Select preventive treatment after the active-disease assessment.**',['Consider source resistance and drug interactions.','TNF blockade increases the importance of a careful evaluation.'],[['Positive IGRA','Evidence of sensitization'],['Active disease','Must be excluded before prevention'],['TNF inhibition','Raises reactivation risk']],[LT,DX],style='clinical_scenario')
q('In the conventional WHO six-month regimen for drug-susceptible pulmonary TB, what does 2HRZE/4HR mean?', 'Two months of isoniazid, rifampicin, pyrazinamide and ethambutol followed by four months of isoniazid and rifampicin',[
 ('Two weeks of four drugs followed by four weeks of two drugs','The prefix numbers indicate months in this notation.'),('Six months of isoniazid alone','Active TB requires an appropriate multidrug regimen.'),('Four months of all four drugs followed by two months of pyrazinamide','This reverses the phases and uses an incorrect continuation regimen.')],
 'Decode the regimen before applying it', '**H is isoniazid, R rifampicin, Z pyrazinamide and E ethambutol.**',['Initial multidrug treatment addresses the bacillary population and resistance risk.','Continuation treatment is needed even when symptoms improve.'], '**Use the current national programme and susceptibility-based protocol.**',['This question specifies the WHO conventional regimen; programme details can differ.','Selected patients may qualify for a validated shorter regimen.'],[['Intensive phase','2 months HRZE'],['Continuation phase','4 months HR'],['Application','Susceptibility and programme guidance']],[TX,CD])
q('Under CDC guidance, which adult is a potential candidate for the four-month rifapentine-moxifloxacin pulmonary TB regimen?', 'A 25-year-old weighing 60 kg with drug-susceptible pulmonary TB and no regimen contraindication or interacting medication',[
 ('A pregnant adult with suspected CNS tuberculosis','Pregnancy and CNS disease are outside the straightforward eligible population.'),('An adult with rifampicin-resistant TB','This is not the drug-susceptible shortened regimen population.'),('An adult with a known fluoroquinolone-resistant isolate','Moxifloxacin is a core component and resistance precludes this choice.')],
 'Shortened treatment requires the correct population and drugs', '**The four-month option uses isoniazid, rifapentine, pyrazinamide and moxifloxacin initially.**',['CDC eligibility includes age at least 12 years and weight at least 40 kg.','Assess resistance, interactions and contraindications.'], '**Do not shorten a different regimen by removing its final months.**',['The validated regimen is a specific combination and schedule.','Extrapulmonary disease, HIV treatment interactions and other complexities need specific guidance.'],[['Eligible phenotype','Appropriate drug-susceptible pulmonary TB'],['Core distinction','Rifapentine and moxifloxacin regimen'],['Not equivalent','Arbitrarily truncated HRZE-based therapy']],[CD],style='clinical_scenario')
q('What defines multidrug-resistant tuberculosis?', 'Resistance to at least isoniazid and rifampicin',[
 ('Resistance to isoniazid alone','This is isoniazid-resistant TB, not by itself MDR-TB.'),('Resistance to any two drugs regardless of which','The defining pair is isoniazid and rifampicin.'),('Resistance to ethambutol and pyrazinamide alone','That pair does not meet the MDR definition.')],
 'Resistance categories depend on specific drugs', '**MDR-TB includes resistance to both H and R.**',['Rifampicin-resistant TB may or may not also have isoniazid resistance.','MDR/RR categories guide further rapid susceptibility testing.'], '**Choose treatment from the complete resistance and eligibility assessment.**',['Additional fluoroquinolone resistance changes options.','Do not infer susceptibility of newer drugs from the MDR label.'],[['H resistance alone','Not MDR'],['H plus R resistance','MDR'],['R resistance','RR, with further characterization needed']],[DR,TX])
q('An isolate is rifampicin-resistant and fluoroquinolone-resistant but remains susceptible to bedaquiline and linezolid. Which WHO resistance category is met?', 'Pre-XDR-TB',[
 ('Drug-susceptible TB','The isolate has important resistance.'),('XDR-TB solely because a fluoroquinolone is resistant','The updated XDR definition also requires resistance to bedaquiline or linezolid.'),('Isoniazid monoresistance','This does not describe the provided profile.')],
 'Use the updated definitions rather than the old injectable-based classification', '**Pre-XDR means MDR/RR-TB with additional fluoroquinolone resistance.**',['XDR additionally includes resistance to at least one of bedaquiline or linezolid.','The old second-line injectable definition is no longer the current WHO definition.'], '**Obtain a treatment-relevant susceptibility profile.**',['Regimen eligibility depends on more than the category name.','Expert and national-programme involvement are important.'],[['MDR/RR plus FQ resistance','Pre-XDR'],['Plus bedaquiline or linezolid resistance','XDR'],['Injectable resistance alone','Not the current defining addition']],[DR],style='clinical_scenario')
q('In an eligible patient receiving the six-month BPaLM regimen for MDR/RR-TB, what does the L denote?', 'Linezolid',[
 ('Levofloxacin','M denotes moxifloxacin; L in this named regimen is linezolid.'),('Liposomal amphotericin B','This is an antifungal, not a component of BPaLM.'),('Lopinavir','This is not a core antituberculosis component of the regimen.')],
 'Understand the components of the named all-oral regimen', '**BPaLM contains bedaquiline, pretomanid, linezolid and moxifloxacin.**',['Eligibility, resistance and previous exposure must be checked.','It is not a universal regimen for every extrapulmonary or resistant-TB presentation.'], '**Monitor drug-specific toxicity during treatment.**',['Linezolid can cause cytopenias and peripheral or optic neuropathy.','QT and other interaction risks also need assessment across the regimen.'],[['B','Bedaquiline'],['Pa / L','Pretomanid / linezolid'],['M','Moxifloxacin']],[TX])
q('Why is adding one new drug to a clearly failing tuberculosis regimen generally inappropriate?', 'It can expose the new drug to functional monotherapy and amplify resistance',[
 ('Symptoms alone prove that every current drug remains active','Persistent symptoms require investigation, not that assumption.'),('A single drug is always enough if the dose is doubled','Effective combination therapy is essential.'),('Resistance testing cannot influence regimen design','Susceptibility evidence is central to selecting an active regimen.')],
 'A failing regimen needs reconstruction, not casual supplementation', '**Investigate adherence, absorption, resistance and alternative explanations.**',['Obtain appropriate specimens for resistance testing.','Review dosing and interactions.'], '**Construct an adequately active regimen with expert programme guidance.**',['The number and selection of drugs depend on the validated regimen and susceptibility profile.','Prevent further resistance while addressing practical barriers to treatment.'],[['Failure assessment','Adherence, exposure and resistance'],['Single addition','Risk of functional monotherapy'],['Corrective strategy','An appropriately active multidrug regimen']],[TX])
q('A patient taking ethambutol reports blurred central vision and altered red-green color perception. What is the priority?', 'Stop ethambutol pending urgent evaluation for optic toxicity and arrange a safe replacement treatment plan',[
 ('Continue unchanged until routine treatment completion','Delay can risk persistent visual injury.'),('Attribute this to harmless rifampicin-related orange discoloration','That discoloration is not the explanation for reduced visual function.'),('Treat with pyridoxine alone while continuing ethambutol','Pyridoxine is not a sufficient response to suspected ethambutol optic toxicity.')],
 'Recognize a potentially vision-threatening adverse effect', '**Ethambutol can cause optic neuropathy.**',['Baseline and follow-up visual assessment are important.','Renal impairment can increase exposure unless dosing is adjusted.'], '**Evaluate promptly while preserving an effective TB regimen.**',['Document acuity and color vision and obtain ophthalmic assessment.','Coordinate the medication change rather than abandoning all treatment.'],[['Drug','Ethambutol'],['Warning','Central vision or color change'],['Action','Urgent assessment and regimen review']],[AE],style='clinical_scenario')
q('A patient receiving isoniazid develops a distal sensory neuropathy. Which intervention addresses a relevant drug-related mechanism?', 'Pyridoxine supplementation with review of dosing and competing neuropathy causes',[
 ('Increasing isoniazid without assessment','This can worsen toxicity.'),('Stopping all TB medicines permanently without a replacement plan','It leaves active disease untreated.'),('Giving folic acid as the specific antidote to pyridoxine depletion','Folate does not replace the relevant vitamin B6 support.')],
 'Isoniazid can disturb pyridoxine-dependent pathways', '**Peripheral neuropathy is a recognized isoniazid adverse effect.**',['Risk rises with factors such as malnutrition, diabetes, HIV or renal disease.','Use preventive pyridoxine in appropriate risk groups according to guidance.'], '**Assess the full clinical picture.**',['Other drugs, diabetes and nutritional deficits can also cause neuropathy.','Severe symptoms require treatment review rather than supplementation alone.'],[['Isoniazid','Neuropathy risk'],['Pyridoxine','Vitamin B6 support'],['Assessment','Risk factors and alternative causes']],[AE,CD],style='clinical_scenario')
